describe('ms(signed string)', function() {
  it('should accept an explicit leading +', function() {
    expect(ms('+1h')).to.be(3600000);
    expect(ms('+1.5 days')).to.be(129600000);
    expect(ms('+.5s')).to.be(500);
  });

  it('should still reject a lone sign', function() {
    expect(isNaN(ms('+'))).to.be(true);
  });
});

