var t = require('assert')
var slugify = require('../')

describe('locale region tags', () => {
  it('uses the base language for a region locale', () => {
    t.equal(slugify('Ä ö & ü', {locale: 'de-DE'}), 'AE-oe-und-ue')
    t.equal(slugify('Ä ö & ü', {locale: 'de_AT'}), 'AE-oe-und-ue')
  })

  it('keeps the default map for unknown locales', () => {
    t.equal(slugify('Ä ö & ü', {locale: 'xx-YY'}), 'A-o-and-u')
    t.equal(slugify('Ä ö & ü'), 'A-o-and-u')
  })
})
